/** Attempt-scoped step timeline. */
import { AsyncLocalStorage } from 'node:async_hooks';
import { isAgentError } from '../agent/error.js';
import { bound } from '../internal/text.js';
import { markAbandonedRejection, relocateStack } from '../internal/abandoned.js';
import { withAiTraceStep } from '../internal/ai-trace.js';
import { classifyError, serializeError, TestError, withHint } from '../internal/errors.js';
import { timestamp } from '../internal/ids.js';
import { withAbort } from '../internal/time.js';
import { sourceLocation } from '../internal/source.js';
import { APP_LOG_LIMITS } from '../engine/session.js';
import { compareScreens } from './step-screens.js';
import { insidePollRead } from '../expect/poll-scope.js';
/** The closed step kind set; the type is derived from it, so the two cannot drift. */
